ALTER POLICY microplan_roles_read_entries ON public.microplan_entries USING ((NOT public.has_active_mda_lens(auth.uid()) OR public.is_admin(auth.uid())) AND public.microplan_row_role_allowed(auth.uid(),project_id,created_by,state,lga,ward,flhf_name,community_name,settlement_name));
ALTER POLICY microplan_roles_read_allocations ON public.microplan_medicine_allocations USING ((NOT public.has_active_mda_lens(auth.uid()) OR public.is_admin(auth.uid())) AND public.microplan_project_access_level(auth.uid(),project_id)='dashboard');
