ALTER POLICY microplan_roles_read_gaps ON public.microplan_missing_communities USING ((NOT public.has_active_mda_lens(auth.uid()) OR public.is_admin(auth.uid())) AND public.microplan_project_access_level(auth.uid(),project_id)='dashboard');